import React, { useCallback } from "react";
import { Link } from "@tanstack/react-router";

// Components
import ShareButton from "../AllProducts/ShareButton";
import Stars from "../AllProducts/Stars";

import { getResponsiveSrcSet } from "../../utils/imageHelpers";

const CategoryCard = React.memo(({ title, description, img, rating, stars, setProductShown, index, link }) => {
	const handleMouseEnter = useCallback(() => {
		setProductShown(index);
	}, [index, setProductShown]);

	return (
		<>
			{/* Category container */}
			<div
				className="w-auto relative overflow-hidden py-3 lg:px-5 px-2 h-[320px] rounded-lg border-[2px] hover:border-[#004B95] bg-white shadow-[0px_4px_20px_rgba(166,166,166,0.3)] mb-8 last-of-type:mb-0 flex flex-col"
				onMouseEnter={handleMouseEnter}
			>
				{/* Category title */}
				<div className="flex justify-between items-center shrink-0">
					<Link to={"/" + link} preload="intent" className="p-2 -m-2">
						<p className={`text-start font-poppins font-bold text-[14px] leading-[131%] tracking-[0.055em] text-[#004B95]`}>{title}</p>
					</Link>
					<ShareButton title={title} link={link} image={img} />
				</div>

				{/* Category image */}
				<div className="flex-grow flex items-center justify-center min-h-0 my-1">
					<Link to={"/" + link} preload="intent" className="block w-full h-full">
						<img className="w-full h-full object-contain" title={title} width="320" height="240" loading="lazy" src={img} srcSet={getResponsiveSrcSet(img)} sizes="(max-width: 640px) 50vw, 320px" alt={title} />
					</Link>
				</div>

				{/* Category rating */}
				<div className="shrink-0 mb-3">
					<Stars rating={rating} stars={stars} />
				</div>

				{/* Link to the products of that category */}
				<div className="text-center shrink-0">
					<Link to={"/" + link} preload="intent">
						<button className="text-center text-[#FFFFFF] lg:text-sm text-xs bg-[#004B95] w-full h-[40px] rounded-[5px] font-poppins font-medium leading-[25.83px] tracking-[6%]" aria-label={"See More Products for " + title}>See More Products</button>
					</Link>
				</div>
			</div>
		</>
	);
});

export default CategoryCard;

